// replaceLast replaces the final occurrence of old in text, if present.
func replaceLast(text, old, replacement string) string {
	i := strings.LastIndex(text, old)
	if i == -1 {
		return text
	}
	return text[:i] + replacement + text[i+len(old):]
}

